import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.Ci_RTJJ5.js";const m=JSON.parse('{"title":"Writing style","description":"","frontmatter":{},"headers":[],"relativePath":"docs/writing-style.md","filePath":"docs/writing-style.md"}'),s={name:"docs/writing-style.md"};function r(n,e,l,c,h,d){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="writing-style" tabindex="-1">Writing style <a class="header-anchor" href="#writing-style" aria-label="Permalink to &quot;Writing style&quot;">​</a></h1><p>Every page in this repository follows these rules. They come from the Querykata house style, which applies three published standards together: Diátaxis for structure, Vercel&#39;s writing guidelines for sentences, and the <code>unslop</code> catalogue for AI tells. The rules below are the operative subset and stand on their own.</p><h2 id="sentences" tabindex="-1">Sentences <a class="header-anchor" href="#sentences" aria-label="Permalink to &quot;Sentences&quot;">​</a></h2><ul><li>Keep a sentence under 25 words. One idea per sentence.</li><li>Use the active voice and the present tense. Append &quot;by monkeys&quot; to a sentence; if it still parses, it is passive, so rewrite it.</li><li>Address the reader as <code>you</code>. Use the imperative for a step.</li><li>Use the short everyday word: use, help, do. Not utilize, facilitate, perform.</li><li>Cut every word that does no work. &quot;In order to&quot; is &quot;to&quot;.</li><li>Name the real symbol, file, flag, or command. The codebase is the word list.</li><li>Do not use an em dash. Use a comma, a colon, or a new sentence.</li><li>Do not say &quot;is&quot; the long way. &quot;Serves as&quot;, &quot;stands as&quot;, and &quot;boasts&quot; are &quot;is&quot;.</li><li>Do not write &quot;not just X, but Y&quot;. State the point.</li><li>Do not force ideas into groups of three. Do not cycle synonyms for one thing. Pick one term and repeat it.</li><li>Do not open a section with a slogan. Do not restate the heading.</li><li>State what a thing does, then point at the file that proves it.</li><li>Prefer a measured number, or a test, over an adjective.</li></ul><h2 id="vocabulary" tabindex="-1">Vocabulary <a class="header-anchor" href="#vocabulary" aria-label="Permalink to &quot;Vocabulary&quot;">​</a></h2><p>Do not use: additionally, crucial, delve, leverage, robust, seamless, showcase, underscore, vibrant, comprehensive, powerful, effortless, unlock, elevate, landscape, realm, journey, testamount, pivotal, meticulous, intricate, ever-evolving, game-changer, best-in-class, cutting-edge, paradigm, synergy, streamline, harness (as a verb), utilize, numerous, myriads.</p><h2 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h2><ul><li>No emoji. No title case in headings. No rhetorical questions.</li><li>A table only when the reader compares values across rows.</li><li>Do not start a list item with a bold label and a dash.</li><li>Say what is unfinished in the same document, in its own section.</li><li>Depth comes from explaining the mechanism and the consequence, not from adding edge cases or repeating the point in new words.</li></ul><h2 id="for-this-course-specifically" tabindex="-1">For this course specifically <a class="header-anchor" href="#for-this-course-specifically" aria-label="Permalink to &quot;For this course specifically&quot;">​</a></h2><ul><li><code>overview.md</code> explains the mechanism. It may not contain a working implementation.</li><li><code>problem.md</code> states the task and the graded claims. It may not teach the concept; it points at the overview for that.</li><li><code>example.md</code> shows a full annotated implementation. It may not introduce a concept that the overview did not already cover.</li><li>Every claim in <code>problem.md</code> names the case id that grades it. If a claim has no case, either the claim is prose or the case is missing. Both are bugs.</li><li>A trap in the prose names the case that catches it. That link is what stops the teaching and the grading from drifting apart.</li></ul>',10)])])}const p=t(s,[["render",r]]);export{m as __pageData,p as default};
